/* rotate around front-back axis */
void rot_x(int a[6]) {
    int t = a[0];
    a[0] = a[3];
    a[3] = a[5];
    a[5] = a[2];
    a[2] = t;
}

/* rotate around left-right axis */
void rot_y(int a[6]) {
    int t = a[0];
    a[0] = a[1];
    a[1] = a[5];
    a[5] = a[4];
    a[4] = t;
}

/* rotate around top-bottom axis */
void rot_z(int a[6]) {
    int t = a[1];
    a[1] = a[3];
    a[3] = a[4];
    a[4] = a[2];
    a[2] = t;
}

int same6(int a[6], int b[6]) {
    for (int i = 0; i < 6; i++) {
        if (a[i] != b[i]) return 0;
    }
    return 1;
}

int equivalent(int a[6], int b[6]) {
    int t[6];
    memcpy(t, a, sizeof(int) * 6);

    /* Generate all 24 orientations */
    for (int cycle = 0; cycle < 6; cycle++) {
        for (int spin = 0; spin < 4; spin++) {
            if (same6(t, b)) return 1;
            rot_z(t);
        }
        if (cycle % 2 == 0) rot_y(t);
        else rot_x(t);
    }
    return 0;
}

