import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    // Face order:
    // 0: top, 1: bottom, 2: front, 3: back, 4: left, 5: right

    static int[] rollNorth(int[] a) {
        return new int[]{a[2], a[3], a[1], a[0], a[4], a[5]};
    }

    static int[] rollSouth(int[] a) {
        return new int[]{a[3], a[2], a[0], a[1], a[4], a[5]};
    }

    static int[] rollWest(int[] a) {
        return new int[]{a[5], a[4], a[2], a[3], a[0], a[1]};
    }

    static int[] rollEast(int[] a) {
        return new int[]{a[4], a[5], a[2], a[3], a[1], a[0]};
    }

    static int[] rotateCW(int[] a) {
        // rotate around vertical axis
        return new int[]{a[0], a[1], a[4], a[5], a[3], a[2]};
    }

    static String encode(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 6; i++) {
            if (i > 0) sb.append(',');
            sb.append(a[i]);
        }
        return sb.toString();
    }

    static String canonical(int[] cube) {
        List<int[]> orientations = new ArrayList<>(24);

        int[] cur = cube.clone();
        for (int i = 0; i < 4; i++) {
            orientations.add(cur);
            int[] spun = cur.clone();
            for (int j = 0; j < 3; j++) {
                spun = rotateCW(spun);
                orientations.add(spun);
            }
            cur = rollNorth(cur);
        }

        cur = rollSouth(cube.clone());
        for (int i = 0; i < 4; i++) {
            orientations.add(cur);
            cur = rotateCW(cur);
        }

        cur = rollNorth(cube.clone());
        for (int i = 0; i < 4; i++) {
            orientations.add(cur);
            cur = rotateCW(cur);
        }

        cur = rollWest(cube.clone());
        for (int i = 0; i < 4; i++) {
            orientations.add(cur);
            cur = rotateCW(cur);
        }

        cur = rollEast(cube.clone());
        for (int i = 0; i < 4; i++) {
            orientations.add(cur);
            cur = rotateCW(cur);
        }

        String best = null;
        for (int[] o : orientations) {
            String s = encode(o);
            if (best == null || s.compareTo(best) < 0) best = s;
        }
        return best;
    }

    static int colorId(String s) {
        switch (s.charAt(0)) {
            case 'R': return 0; // Red
            case 'Y': return 1; // Yellow
            case 'B': return 2; // Blue
            case 'M': return 3; // Magenta
            case 'G': return 4; // Green
            case 'C': return 5; // Cyan
        }
        return -1;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        Set<String> set = new HashSet<>();

        for (int i = 0; i < n; i++) {
            int[] cube = new int[6];
            for (int j = 0; j < 6; j++) {
                cube[j] = colorId(fs.next());
            }
            set.add(canonical(cube));
        }

        System.out.println(set.size());
    }
